/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,14],[14,36],[36,58],[58,80]]);
  v.dO = lin([[0,0],[3,1],[10,1],[13,0]]); v.dT = 'translateY(' + lin([[0,-50],[3,0],[10,0],[13,30]]).toFixed(1) + 'px) scale(' + lin([[0,.9],[3,1],[10,1],[13,.6]]).toFixed(3) + ')';
  v.cad = lin([[8,0],[13,1],[56,1],[64,0.25]]) * out;
  var c = lin([[16,0],[30,1]]), b = lin([[38,0],[52,1]]), s = lin([[60,0],[70,1]]);
  v.gc = 'opacity: ' + (c * out).toFixed(3) + '; transform: translateY(' + (12 * (1 - c)).toFixed(1) + 'px);';
  v.gb = 'opacity: ' + (b * out).toFixed(3) + '; transform: translateY(' + (-12 * (1 - b)).toFixed(1) + 'px);';
  v.gs = 'opacity: ' + (s * out).toFixed(3) + '; transform: translateY(' + (-16 * (1 - s)).toFixed(1) + 'px);';
  v.nc = Math.round(12 * c); v.nb = Math.round(17 * b); v.nw = Math.round(3 * b); v.ns = s > 0.5 ? 1 : 0;
  v.fin = (p >= 72 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
